import os, re

# Load all grids from current instance (this reads the session log)
d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
log_path = os.path.join(os.path.dirname(d), '..', 'sessions', os.path.basename(d) + '.jsonl')
print(f"Log path: {log_path}")

# Try reading the log
try:
    with open(log_path, 'r') as f:
        content = f.read()
    print(f"Log content preview ({len(content)} chars):")
    print(content[:2000])
except Exception as e:
    print(f"Error reading log: {e}")

# Try to load grids
import json
all_grids = {}
for line in content.split('\n'):
    try:
        msg = json.loads(line)
        if 'action' in msg:
            if msg['action'] == 'request_demos_so_far':
                print(f"Demos requested so far: {msg.get('demos_requested_so_far', 0)} / {msg.get('cap', 8)}")
            elif msg['action'] == 'demo_pair':
                for demo in msg.get('demo_pair', []):
                    key = f"{demo['width']}x{demo['height']} ({demo['id']})"
                    if key not in all_grids:
                        all_grids[key] = {}
                    all_grids[key][demo['type']] = demo['grid']
            elif msg['action'].startswith('Demo pair') or 'test input' in msg.get('action', '').lower():
                # Parse grid from action or message
                pass
    except:
        pass

print(f"\nLoaded grids: {list(all_grids.keys())}")
